import{_ as i,o as e,c as l,ag as t}from"./chunks/framework.DGzMGr_a.js";const _=JSON.parse('{"title":"GRAVITY 愿景发表会：RO3 赛季制确认、千人同屏攻城战","description":"GRAVITY 2026 年度愿景发表会，RO3 将导入赛季制并挑战千人同屏攻城战","frontmatter":{"title":"GRAVITY 愿景发表会：RO3 赛季制确认、千人同屏攻城战","description":"GRAVITY 2026 年度愿景发表会，RO3 将导入赛季制并挑战千人同屏攻城战"},"headers":[],"relativePath":"news/gravity-vision-202512.md","filePath":"news/gravity-vision-202512.md","lastUpdated":1779114110000}'),r={name:"news/gravity-vision-202512.md"};function o(n,a,s,d,h,c){return e(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="gravity-愿景发表会-ro3-赛季制、千人攻城战" tabindex="-1">GRAVITY 愿景发表会：RO3 赛季制、千人攻城战 <a class="header-anchor" href="#gravity-愿景发表会-ro3-赛季制、千人攻城战" aria-label="Permalink to &quot;GRAVITY 愿景发表会：RO3 赛季制、千人攻城战&quot;">​</a></h1><p>日期：2025-12-14</p><p>GRAVITY 在泰国曼谷举办 2026 年度愿景发表会，一口气揭露四款 RO IP 新作规划。其中 RO3 宣布将挑战 MMO 史上首次「千人同画面」攻城战，并确认导入创新赛季制。</p><h2 id="ro3-核心亮点" tabindex="-1">RO3 核心亮点 <a class="header-anchor" href="#ro3-核心亮点" aria-label="Permalink to &quot;RO3 核心亮点&quot;">​</a></h2><h3 id="赛季制-mmo" tabindex="-1">赛季制 MMO <a class="header-anchor" href="#赛季制-mmo" aria-label="Permalink to &quot;赛季制 MMO&quot;">​</a></h3><p>每个赛季为期 3 个月，这是全球首款赛季制 MMO。赛季期间包含激烈的领地争夺战，未来将推出投票让玩家选出想复刻的赛季。</p><h3 id="千人同屏攻城战" tabindex="-1">千人同屏攻城战 <a class="header-anchor" href="#千人同屏攻城战" aria-label="Permalink to &quot;千人同屏攻城战&quot;">​</a></h3><ul><li>MMO 史上首次实现 1,000 人同场景且无需切换地图</li><li>支援 100v100 攻城战，单场持续 45 分钟</li><li>包含攻城器械、粮草运输等多层次战略机制</li><li>公会之间可选择结盟或截击粮草，充满战术变数</li></ul><h3 id="_2026-年计划" tabindex="-1">2026 年计划 <a class="header-anchor" href="#_2026-年计划" aria-label="Permalink to &quot;2026 年计划&quot;">​</a></h3><ul><li>将在巴西进行千人攻城战测试</li><li>全球同步上线目标不变</li><li>兼顾 PC 与移动端体验</li></ul><h3 id="新手友好设计" tabindex="-1">新手友好设计 <a class="header-anchor" href="#新手友好设计" aria-label="Permalink to &quot;新手友好设计&quot;">​</a></h3><ul><li>针对 PC 为主要开发平台，同时优化移动端操作</li><li>技能设计兼顾策略性与操作性</li><li>提供职业推荐系统帮助新手快速上手</li></ul><p><small>消息来源：巴哈姆特 GNN 现场采访整理</small></p>',13)])])}const m=i(r,[["render",o]]);export{_ as __pageData,m as default};
